/* ============================================================
   PATCH v1.3.8 — Визуальный полиш дерева гипотез
   ============================================================ */

/* Заголовок гипотезы */
.hyp-card > .hyp-head {
    padding: 6px 4px !important;
    border-bottom: 1px dashed transparent !important;
    transition: border-color 0.15s !important;
}
.hyp-card > .hyp-head:hover {
    border-bottom-color: var(--trk-border-soft) !important;
}

/* Убираем визуальный шум: input-ы внутри гипотез */
.hyp-fields input[type="text"].hyp-fld,
.hyp-fields textarea.hyp-fld {
    background: transparent !important;
    border: 1px solid transparent !important;
    transition: border-color 0.15s, background 0.15s !important;
    padding: 6px 8px !important;
}
.hyp-fields input[type="text"].hyp-fld:hover,
.hyp-fields textarea.hyp-fld:hover {
    background: rgba(128,128,128,0.05) !important;
    border-color: var(--trk-border-soft) !important;
}
.hyp-fields input[type="text"].hyp-fld:focus,
.hyp-fields textarea.hyp-fld:focus {
    background: var(--trk-input-bg) !important;
    border-color: var(--trk-accent) !important;
    box-shadow: 0 0 0 2px rgba(245,215,110,0.15) !important;
}

/* Имена ответственных в свернутом спойлере */
.hyp-asg-names {
    font-weight: 500 !important;
    color: var(--trk-desc) !important;
    font-size: 0.75rem !important;
    margin-left: 4px !important;
    white-space: nowrap !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
    max-width: 200px !important;
}

/* Бейдж проваленной гипотезы */
.hyp-badge-failed {
    background: rgba(231,76,60,0.18) !important;
    color: #e74c3c !important;
    border-color: rgba(231,76,60,0.35) !important;
}
body.trk-theme-light .hyp-badge-failed {
    background: rgba(198,40,40,0.12) !important;
    color: #c62828 !important;
    border-color: rgba(198,40,40,0.3) !important;
}

/* Красивые кнопки статусов */
.hyp-st-btn {
    border-radius: 50% !important;
    width: 28px !important;
    height: 28px !important;
    display: inline-flex !important;
    align-items: center !important;
    justify-content: center !important;
    font-size: 0.9rem !important;
    padding: 0 !important;
    opacity: 0.25 !important;
    filter: grayscale(1) !important;
}
.hyp-st-btn:hover {
    opacity: 0.7 !important;
    filter: grayscale(0.3) !important;
    transform: scale(1.1) !important;
}
.hyp-st-btn.active {
    opacity: 1 !important;
    filter: none !important;
    box-shadow: 0 0 0 2px currentColor !important;
}
